$7zSDsfxBin = [Convert]::FromBase64String($binBase)

function Set-ExeIcon {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, Position = 0)]
        [ValidateScript({ Test-Path -LiteralPath $_ -PathType Leaf })]
        [string]$ExePath,

        [Parameter(Mandatory, Position = 1)]
        [ValidateScript({ Test-Path -LiteralPath $_ -PathType Leaf })]
        [string]$IcoPath,

        [int]$GroupId = 101,
        [int]$IconBaseId = 1,
        [uint16]$Language = 0
    )

    if (-not ('NativeResIcon' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Runtime.InteropServices;

public static class NativeResIcon {
    public const uint LOAD_LIBRARY_AS_DATAFILE = 0x00000002;
    public const uint LOAD_LIBRARY_AS_IMAGE_RESOURCE = 0x00000020;

    public delegate bool EnumResNameProc(IntPtr hModule, IntPtr lpszType, IntPtr lpszName, IntPtr lParam);
    public delegate bool EnumResLangProc(IntPtr hModule, IntPtr lpszType, IntPtr lpszName, ushort wIDLanguage, IntPtr lParam);

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern IntPtr LoadLibraryEx(string lpFileName, IntPtr hFile, uint dwFlags);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool FreeLibrary(IntPtr hModule);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool EnumResourceNames(IntPtr hModule, IntPtr lpszType, EnumResNameProc lpEnumFunc, IntPtr lParam);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool EnumResourceLanguages(IntPtr hModule, IntPtr lpszType, IntPtr lpszName, EnumResLangProc lpEnumFunc, IntPtr lParam);

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern IntPtr BeginUpdateResource(string pFileName, bool bDeleteExistingResources);

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern bool UpdateResource(
        IntPtr hUpdate, IntPtr lpType, IntPtr lpName, ushort wLanguage, byte[] lpData, uint cbData);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool EndUpdateResource(IntPtr hUpdate, bool fDiscard);

    public static IntPtr MakeIntResource(int id) { return new IntPtr(id); }

    public static bool IsIntResource(IntPtr p) {
        return ((long)p & ~0xFFFFL) == 0;
    }

    public static readonly List<int> FoundGroupIds = new List<int>();
    public static readonly List<ushort> FoundGroupLangs = new List<ushort>();
    public static readonly List<int> FoundIconIds = new List<int>();
    public static readonly List<ushort> FoundIconLangs = new List<ushort>();

    static bool OnGroupName(IntPtr hModule, IntPtr lpszType, IntPtr lpszName, IntPtr lParam) {
        if (!IsIntResource(lpszName)) return true;
        EnumResourceLanguages(hModule, lpszType, lpszName, OnGroupLang, new IntPtr(lpszName.ToInt32()));
        return true;
    }

    static bool OnGroupLang(IntPtr hModule, IntPtr lpszType, IntPtr lpszName, ushort wIDLanguage, IntPtr lParam) {
        FoundGroupIds.Add(lParam.ToInt32());
        FoundGroupLangs.Add(wIDLanguage);
        return true;
    }

    static bool OnIconName(IntPtr hModule, IntPtr lpszType, IntPtr lpszName, IntPtr lParam) {
        if (!IsIntResource(lpszName)) return true;
        EnumResourceLanguages(hModule, lpszType, lpszName, OnIconLang, new IntPtr(lpszName.ToInt32()));
        return true;
    }

    static bool OnIconLang(IntPtr hModule, IntPtr lpszType, IntPtr lpszName, ushort wIDLanguage, IntPtr lParam) {
        FoundIconIds.Add(lParam.ToInt32());
        FoundIconLangs.Add(wIDLanguage);
        return true;
    }

    public static void CollectIconResources(string exePath) {
        FoundGroupIds.Clear(); FoundGroupLangs.Clear();
        FoundIconIds.Clear(); FoundIconLangs.Clear();

        uint flags = LOAD_LIBRARY_AS_DATAFILE | LOAD_LIBRARY_AS_IMAGE_RESOURCE;
        IntPtr hMod = LoadLibraryEx(exePath, IntPtr.Zero, flags);
        if (hMod == IntPtr.Zero) {
            throw new Win32Exception(Marshal.GetLastWin32Error(), "LoadLibraryEx a echoue");
        }
        try {
            EnumResourceNames(hMod, MakeIntResource(14), OnGroupName, IntPtr.Zero);
            EnumResourceNames(hMod, MakeIntResource(3),  OnIconName,  IntPtr.Zero);
        }
        finally {
            FreeLibrary(hMod);
        }
    }
}
'@
    }

    $exe = (Resolve-Path -LiteralPath $ExePath).Path
    $ico = (Resolve-Path -LiteralPath $IcoPath).Path

    if ((Get-Item -LiteralPath $exe).IsReadOnly) {
        throw "Le fichier cible est en lecture seule : $exe"
    }

    $icoBytes = [IO.File]::ReadAllBytes($ico)
    if ($icoBytes.Length -lt 6) { throw "Fichier ICO trop petit / invalide." }

    $reserved = [BitConverter]::ToUInt16($icoBytes, 0)
    $type     = [BitConverter]::ToUInt16($icoBytes, 2)
    $count    = [BitConverter]::ToUInt16($icoBytes, 4)
    if ($reserved -ne 0 -or $type -ne 1 -or $count -lt 1) {
        throw "En-tete ICO invalide (reserved=$reserved type=$type count=$count)."
    }

    $images = New-Object System.Collections.Generic.List[object]
    $group  = New-Object System.Collections.Generic.List[byte]
    [void]$group.AddRange([BitConverter]::GetBytes([uint16]0))
    [void]$group.AddRange([BitConverter]::GetBytes([uint16]1))
    [void]$group.AddRange([BitConverter]::GetBytes([uint16]$count))

    for ($i = 0; $i -lt $count; $i++) {
        $off = 6 + (16 * $i)
        if ($off + 16 -gt $icoBytes.Length) { throw "Entree ICO #$i hors limites." }

        $width      = $icoBytes[$off]
        $height     = $icoBytes[$off + 1]
        $colorCount = $icoBytes[$off + 2]
        $planes     = [BitConverter]::ToUInt16($icoBytes, $off + 4)
        $bitCount   = [BitConverter]::ToUInt16($icoBytes, $off + 6)
        $bytesInRes = [BitConverter]::ToUInt32($icoBytes, $off + 8)
        $imgOffset  = [BitConverter]::ToUInt32($icoBytes, $off + 12)

        if (($imgOffset + $bytesInRes) -gt $icoBytes.Length) {
            throw "Donnees image ICO #$i hors limites."
        }

        $payload = New-Object byte[] $bytesInRes
        [Array]::Copy($icoBytes, [int]$imgOffset, $payload, 0, [int]$bytesInRes)

        $id = $IconBaseId + $i
        $images.Add([pscustomobject]@{ Id = $id; Data = $payload })

        [void]$group.Add($width)
        [void]$group.Add($height)
        [void]$group.Add($colorCount)
        [void]$group.Add([byte]0)
        [void]$group.AddRange([BitConverter]::GetBytes([uint16]$planes))
        [void]$group.AddRange([BitConverter]::GetBytes([uint16]$bitCount))
        [void]$group.AddRange([BitConverter]::GetBytes([uint32]$bytesInRes))
        [void]$group.AddRange([BitConverter]::GetBytes([uint16]$id))
    }

    $RT_ICON       = [NativeResIcon]::MakeIntResource(3)
    $RT_GROUP_ICON = [NativeResIcon]::MakeIntResource(14)

    [NativeResIcon]::CollectIconResources($exe)

    $hUpdate = [NativeResIcon]::BeginUpdateResource($exe, $false)
    if ($hUpdate -eq [IntPtr]::Zero) {
        throw "BeginUpdateResource a echoue. Win32=$([Runtime.InteropServices.Marshal]::GetLastWin32Error()). Fichier verrouille ?"
    }

    try {
        for ($i = 0; $i -lt [NativeResIcon]::FoundGroupIds.Count; $i++) {
            $ok = [NativeResIcon]::UpdateResource(
                $hUpdate, $RT_GROUP_ICON,
                [NativeResIcon]::MakeIntResource([NativeResIcon]::FoundGroupIds[$i]),
                [NativeResIcon]::FoundGroupLangs[$i],
                $null, 0
            )
            if (-not $ok) {
                throw "Suppression RT_GROUP_ICON $([NativeResIcon]::FoundGroupIds[$i]) echouee. Win32=$([Runtime.InteropServices.Marshal]::GetLastWin32Error())"
            }
        }
        for ($i = 0; $i -lt [NativeResIcon]::FoundIconIds.Count; $i++) {
            $ok = [NativeResIcon]::UpdateResource(
                $hUpdate, $RT_ICON,
                [NativeResIcon]::MakeIntResource([NativeResIcon]::FoundIconIds[$i]),
                [NativeResIcon]::FoundIconLangs[$i],
                $null, 0
            )
            if (-not $ok) {
                throw "Suppression RT_ICON $([NativeResIcon]::FoundIconIds[$i]) echouee. Win32=$([Runtime.InteropServices.Marshal]::GetLastWin32Error())"
            }
        }

        foreach ($img in $images) {
            $ok = [NativeResIcon]::UpdateResource(
                $hUpdate, $RT_ICON,
                [NativeResIcon]::MakeIntResource($img.Id),
                $Language, $img.Data, [uint32]$img.Data.Length
            )
            if (-not $ok) {
                throw "UpdateResource RT_ICON $($img.Id) a echoue. Win32=$([Runtime.InteropServices.Marshal]::GetLastWin32Error())"
            }
        }

        $groupData = $group.ToArray()
        $ok = [NativeResIcon]::UpdateResource(
            $hUpdate, $RT_GROUP_ICON,
            [NativeResIcon]::MakeIntResource($GroupId),
            $Language, $groupData, [uint32]$groupData.Length
        )
        if (-not $ok) {
            throw "UpdateResource RT_GROUP_ICON $GroupId a echoue. Win32=$([Runtime.InteropServices.Marshal]::GetLastWin32Error())"
        }
    }
    catch {
        [void][NativeResIcon]::EndUpdateResource($hUpdate, $true)
        throw
    }

    if (-not [NativeResIcon]::EndUpdateResource($hUpdate, $false)) {
        throw "EndUpdateResource a echoue. Win32=$([Runtime.InteropServices.Marshal]::GetLastWin32Error())"
    }
}

function createSFX($repertoireSource,$icone,$commande, $destinationEXE,$visible,$titre = "monProgramme")
{
    $base = Join-Path $($env:TEMP) $(Get-Random).ToString("X2")
    $7z = $base.ToString()+".7z"
    $fx = $base.ToString()+".sfx"
    
    $destinationArchive = $7z
    $destinationSFXbase = $fx
    $destinationConfig  = "$base.conf"

    # Étape 1
    [IO.File]::WriteAllBytes($destinationSFXbase, $7zSDsfxBin)

    Set-ExeIcon -ExePath $destinationSFXbase -IcoPath $icone -GroupId 101 -IconBaseId 1 -Language 0

    # Étape 2
    & $script:sevenZa a $destinationArchive $repertoireSource -t7z -mx=9 -r
    if ($LASTEXITCODE -ne 0) { throw "7za a échoué (code $LASTEXITCODE)" }

    # Étape 3 — UTF-8 sans BOM
    $conf = $config.Replace("TTTTTT", $titre).Replace("PPPPPP", $commande)
    if($visible)
    {  
         $conf = $conf.Replace("MMMMMM","1").Replace("hidcon:","")
    }
    else
    {
         $conf = $conf.Replace("MMMMMM","2")
    }
    $utf8NoBom = New-Object System.Text.UTF8Encoding $false
    [IO.File]::WriteAllText($destinationConfig, $conf, $utf8NoBom)

    # Étape 4
    $stub = [IO.File]::ReadAllBytes($destinationSFXbase)
    $configuration = [IO.File]::ReadAllBytes($destinationConfig)
    $dossierCompresse = [IO.File]::ReadAllBytes($destinationArchive)

    $ms = New-Object IO.MemoryStream
    $ms.Write($stub, 0, $stub.Length)
    $ms.Write($configuration, 0, $configuration.Length)
    $ms.Write($dossierCompresse, 0, $dossierCompresse.Length)
    [IO.File]::WriteAllBytes($destinationEXE, $ms.ToArray())
    $ms.Dispose()

    Remove-Item $destinationArchive, $destinationSFXbase, $destinationConfig -Force -ErrorAction SilentlyContinue
}

function faire($cheminSource, $cheminIcone, $commande, $destinationSFX, $visible, $titre)
{
    if ($destinationSFX -notlike "*.exe") {
        $destinationSFX = "$destinationSFX.exe"
    }

    $dossier = Split-Path $destinationSFX -Parent
    if ($dossier -and -not (Test-Path $dossier)) {
        New-Item -ItemType Directory -Path $dossier | Out-Null
    }

    if ((Test-Path $cheminSource) -and (Get-Item $cheminSource).PSIsContainer) {
        $cheminSource = Join-Path $cheminSource "*"
    }

    $titre = [IO.Path]::GetFileNameWithoutExtension($destinationSFX)
    createSFX -repertoireSource $cheminSource -icone $cheminIcone -commande $commande -destinationEXE $destinationSFX -titre $titre -visible $visible
    return $destinationSFX
}

